// AuthModal.js
import { useState, useEffect } from 'react';
import Login from './Login';
import Register from './Register';

const AuthModal = ({ isOpen, onClose }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      setTimeout(() => setShowModal(true), 10);
    } else {
      document.body.style.overflow = 'unset';
      setShowModal(false);
    }

    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  // Fermer avec la touche ESC
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === 'Escape') onClose();
    };

    if (isOpen) {
      window.addEventListener('keydown', handleEsc);
    }

    return () => {
      window.removeEventListener('keydown', handleEsc);
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleOverlayClick = (e) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  return (
    <div 
      className="fixed inset-0 z-50 overflow-y-auto"
      onClick={handleOverlayClick}
    >
      {/* Overlay avec animation */}
      <div 
        className={`fixed inset-0 bg-black transition-opacity duration-300 ${
          showModal ? 'bg-opacity-60' : 'bg-opacity-0'
        }`}
      />

      {/* Modal */}
      <div className="flex min-h-screen items-center justify-center p-4">
        <div 
          className={`relative w-full max-w-md transform transition-all duration-300 ${
            showModal ? 'scale-100 opacity-100' : 'scale-95 opacity-0'
          }`}
        >
          {/* Onglets */}
          <div className="flex mb-6 rounded-t-2xl overflow-hidden shadow-lg">
            <button
              onClick={() => setIsLogin(true)}
              className={`flex-1 py-4 text-lg font-bold transition-all duration-300 relative group ${
                isLogin
                  ? 'bg-gradient-to-r from-blue-600 to-cyan-500 text-white'
                  : 'bg-white text-gray-600 hover:text-blue-600'
              }`}
            >
              {isLogin && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-white transform transition-transform duration-300" />
              )}
              <span className="relative z-10">Connexion</span>
              <div className={`absolute inset-0 opacity-0 group-hover:opacity-10 transition-opacity ${
                isLogin ? 'bg-white' : 'bg-blue-500'
              }`} />
            </button>

            <button
              onClick={() => setIsLogin(false)}
              className={`flex-1 py-4 text-lg font-bold transition-all duration-300 relative group ${
                !isLogin
                  ? 'bg-gradient-to-r from-green-600 to-emerald-500 text-white'
                  : 'bg-white text-gray-600 hover:text-green-600'
              }`}
            >
              {!isLogin && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-white transform transition-transform duration-300" />
              )}
              <span className="relative z-10">Inscription</span>
              <div className={`absolute inset-0 opacity-0 group-hover:opacity-10 transition-opacity ${
                !isLogin ? 'bg-white' : 'bg-green-500'
              }`} />
            </button>
          </div>

          {/* Contenu */}
          <div className="bg-white rounded-2xl shadow-2xl overflow-hidden">
            {isLogin ? (
              <Login 
                onClose={onClose}
                switchToRegister={() => setIsLogin(false)}
              />
            ) : (
              <Register 
                onClose={onClose}
                switchToLogin={() => setIsLogin(true)}
              />
            )}
          </div>

          {/* Info de sécurité */}
          <div className="mt-6 text-center animate-fadeIn">
            <div className="inline-flex items-center space-x-2 bg-gray-50 rounded-full px-4 py-2">
              <svg className="w-4 h-4 text-green-500" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
              </svg>
              <p className="text-xs text-gray-600">
                Vos données sont sécurisées et chiffrées
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthModal;
